import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
const bus = new HookBus(); const order: string[] = [];
bus.on("e", async () => { await new Promise(r => setTimeout(r, 20)); order.push("a"); });
const offB = bus.on("e", () => { order.push("b"); offB(); offB(); });
bus.on("e", () => { order.push("c"); });
await bus.emit("e", 1);
assert.deepEqual(order, ["a","b","c"]);
assert.equal(bus.count("e"), 2);
const err = new Error("boom"); let after = false;
bus.on("x", async () => { throw err; }); bus.on("x", () => { after = true; });
await assert.rejects(bus.emit("x", 1), (e) => e === err);
assert.equal(after, false);
console.log("contract checks OK");

